thm:radical.statement:
\label{thm:radical}
$\Nrad=\{0\}$ for every value of the constant $c$: the form $I_A$ is
nondegenerate on $\DA$.

\label{thm:radical}
Let $S$ be a chart and $c\in\R$.  For all $h,g\in C_c^\infty(\R)$,
\begin{equation}
\label{eq:radform}
  I^{(c)}_S(\Gamma_h,\Gamma_g)
  =\frac1{2\pi}\int_\R\hat h(\tau)\,\overline{\hat g(\tau)}\,
     \bigl(\widehat T_S(\cz,\tau)+c\bigr)\,d\tau ,
\end{equation}
the integral being absolutely convergent.  If $h\in C_c^\infty(\R)$ and
$I^{(c)}_S(\Gamma_h,\Gamma_g)=0$ for every $g\in C_c^\infty(\R)$, then $h=0$.
Thus the restriction of $I^{(c)}_S$ to the subalgebra $\DAr(S)$ of radial
functions is nondegenerate.

prop:tate.statement:
[{\cite[Theorem~5.11]{P43}}]
\label{prop:tate}
The functionals
\begin{equation}
\label{eq:tatefunctionals}
  \lambda_\mp(F):=\int_{\CS}F(u)\,|u|_S^{\mp1/2}\,d^*u
\end{equation}
on $\DA(S)$ are multiplicative for $\star$ and satisfy
$\lambda_\mp(F^\dagger)=\overline{\lambda_\pm(F)}$.  The map
$M:=(\lambda_-,\lambda_+)$ is a surjective homomorphism of algebras from
$\DA(S)$ to $\C^2$.  On $\C^2$, with coordinates $z=(z_-,z_+)$, we use the
nondegenerate Hermitian form
\begin{equation}
\label{eq:betaT}
  \beta_T(z,w)=z_-\overline{w_+}+z_+\overline{w_-} .
\end{equation}

lem:K.statement:
[the L\'evy density]\label{lem:K}
For $u>0$ put $K(u)=\dfrac{2e^{3u/2}}{e^{2u}-1}=\dfrac{1}{2\sinh(u/2)}+\dfrac{1}{2\cosh(u/2)}
=2\sum_{k\ge0}e^{-(2k+\frac12)u}$. Then $K$ is positive, completely monotone,
$K(u)=u^{-1}+O(1)$ as $u\downarrow0$, $K(u)=2e^{-u/2}(1+O(e^{-u}))$ as $u\to\infty$, and
\begin{equation}\label{eq:m}
\begin{split}
m(\tau)&=\Rel\psi\!\left(\tfrac14+\tfrac{i\tau}2\right)-\log\pi
= C_0+\int_0^\infty(1-\cos\tau u)\,K(u)\,du,\\
C_0&=\psi(\tfrac14)-\log\pi=-5.3721834\ldots
\end{split}
\end{equation}

