pex:sharp.statement:
[Sharpness and the finite masses]\label{pex:sharp}
Let $J\subseteq K^1$ be the group of the integral points $\equiv1$ at the places of $\mathsf M$
(no condition at the places of $Q$).
\begin{enumerate}
\item[(a)] $\Psi_\vartheta$ is sharp for $J$ ({\cite[Definition~2.15]{P53}}, for the modulus
$\mathfrak m$ and the character $\alpha$).
\item[(b)] $\|\Psi_\vartheta\|^2/\#\pexMat_{2z\times1}(\pcR_{\mathfrak m})=\prod_{w\in\mathsf M}q_w^{-2z}
\cdot\prod_{w\in Q}(q_w-1)/q_w$, and $[K^1:J]=\prod_{w\in\mathsf M}(q_w-1)$.
\item[(c)] $[K_{V^{(z)}}:\pexK_\vartheta]=c_{\mathsf M}\prod_{w\in Q}\dfrac{q_w^{2z}-1}{q_w-1}$, with
$c_{\mathsf M}=\prod_{w\in\mathsf M}(q_w^{2z}-1)$ independent of $\vartheta$.
\end{enumerate}

[Sharpness and the finite masses]\label{pex:sharp}
Let $J\subseteq K^1$ be the group of the integral points $\equiv1$ at the places of $\mathsf M$
(no condition at the places of $Q$).
\begin{enumerate}
\item[(a)] $\Psi_\vartheta$ is sharp for $J$ (Definition~\ref{pc:sharp}, for the modulus
$\mathfrak m$ and the character $\alpha$).
\item[(b)] $\|\Psi_\vartheta\|^2/\#\pexMat_{2z\times1}(\pcR_{\mathfrak m})=\prod_{w\in\mathsf M}q_w^{-2z}
\cdot\prod_{w\in Q}(q_w-1)/q_w$, and $[K^1:J]=\prod_{w\in\mathsf M}(q_w-1)$.
\item[(c)] $[K_{V^{(z)}}:\pexK_\vartheta]=c_{\mathsf M}\prod_{w\in Q}\dfrac{q_w^{2z}-1}{q_w-1}$, with
$c_{\mathsf M}=\prod_{w\in\mathsf M}(q_w^{2z}-1)$ independent of $\vartheta$.
\end{enumerate}

pte:conj.statement:
[Negation]\label{pte:conj}
Let $S_1,T$ be spaces of ranks $n_1,n'$ and $S_1^-$ the space with the same frame and the negated form. There is
$\epsilon\in\C$, $|\epsilon|=1$, such that for all characters $a,b$, moduli $\pcm$, functions $\Psi$, polynomials $P$,
and $g,h$, $\aubar{\theta^{S_1,T}_{b,a}(g,h;[P,\Psi])}=\epsilon\,\theta^{S_1^-,T}_{b^{-1}\upsilon^{n'},a^{-1}\upsilon^{n_1}}
(g,h;[\aubar P,\aubar\Psi])$, where $\aubar P$ has conjugate coefficients and $\auU(S_1^-)=\auU(S_1)$ (the source
character is shifted by $\upsilon$ to the rank of $T$, the target character by $\upsilon$ to the rank of $S_1$).

